import{_ as r,o as a,c as t,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"3D Printer Card","description":"Carte compacte Home Assistant pour Klipper et Moonraker avec profils, caméra et courbes de température.","frontmatter":{"title":"3D Printer Card","description":"Carte compacte Home Assistant pour Klipper et Moonraker avec profils, caméra et courbes de température."},"headers":[],"relativePath":"fr/projects/3d-printer-card/index.md","filePath":"fr/projects/3d-printer-card/index.md","lastUpdated":1795794293000}'),n={name:"fr/projects/3d-printer-card/index.md"};function s(o,e,l,c,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_3d-printer-card" tabindex="-1">3D Printer Card <a class="header-anchor" href="#_3d-printer-card" aria-label="Permalink to &quot;3D Printer Card&quot;">​</a></h1><p><a href="/projects/3d-printer-card/">Deutsch</a> · <a href="/en/projects/3d-printer-card/">English</a></p><p><strong>Version 0.1.6. Fonctionne uniquement avec Klipper et Moonraker.</strong> L&#39;<a href="https://github.com/marcolivierarsenault/moonraker-home-assistant" target="_blank" rel="noreferrer">intégration Moonraker</a> doit être installée et configurée pour chaque imprimante. La carte utilise ses entités HA sans identifiants ni connexion supplémentaires.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=3d-printer-card&amp;category=plugin" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Ouvrir dans HACS"></a></p><ol><li>Sauvegardez les paramètres. Installez et configurez l&#39;<a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=marcolivierarsenault&amp;repository=moonraker-home-assistant&amp;category=integration" target="_blank" rel="noreferrer">intégration Moonraker dans HACS</a>.</li><li>Ajoutez <code>https://github.com/rockbaer2007/3d-printer-card</code> comme dépôt personnalisé <strong>Dashboard</strong> dans HACS et téléchargez-le. Pas encore au catalogue HACS par défaut.</li><li>Vérifiez la ressource <code>/hacsfiles/3d-printer-card/3d-printer-card.js</code>, de type <strong>module JavaScript</strong>, puis rechargez le navigateur. Remplacez l&#39;ancienne ressource locale sans charger les deux versions.</li><li>Ajoutez <strong>3D Printer Card</strong>. Le type reste <code>custom:moonraker-display-card</code>.</li></ol><p>Installation manuelle : copiez le fichier JS dans <code>/config/www/3d-printer-card/</code> et enregistrez <code>/local/3d-printer-card/3d-printer-card.js?v=0.1.6</code> comme module JavaScript. Aucun redémarrage HA nécessaire. Remplacez toutes les entités d&#39;exemple.</p><h2 id="affichage-et-profils" tabindex="-1">Affichage et profils <a class="header-anchor" href="#affichage-et-profils" aria-label="Permalink to &quot;Affichage et profils&quot;">​</a></h2><ul><li>État, fichier, progression, durées écoulée/restante/estimée, heure de fin, couches, vitesse, ventilateur et messages.</li><li>Températures réelle/cible de la buse et du plateau dans un graphique ; températures réelles de la carte et du pad dans un autre. L&#39;historique nécessite ces entités dans HA Recorder.</li><li>Caméra à droite sur environ un tiers de la largeur, miniature optionnelle. Sur petit écran, les éléments sont empilés.</li><li>Champs compacts, graphiques peu hauts, largeur initiale de 24 colonnes et hauteur automatique. Utilisez une vue en sections ; une vue panneau impose la pleine largeur.</li><li>Jusqu&#39;à 20 profils avec leurs propres entités et caméras.</li></ul><p>Dans l&#39;éditeur, ouvrez <strong>Profil hinzufügen</strong> (ajouter) ou <strong>Profil bearbeiten</strong> (modifier). Sélectionnez le capteur <code>current_print_state</code> dans <strong>Drucker erkennen</strong> pour détecter le préfixe. Adaptez les caméras et correspondances avec les sélecteurs HA natifs. Cliquez sur <strong>Profil übernehmen</strong>, puis <strong>Speichern</strong> dans l&#39;éditeur principal. Éditeur actuellement en allemand ; documentation DE/EN/FR. Les profils existants restent compatibles.</p><h2 id="annulation-et-verifications" tabindex="-1">Annulation et vérifications <a class="header-anchor" href="#annulation-et-verifications" aria-label="Permalink to &quot;Annulation et vérifications&quot;">​</a></h2><p>La seule commande est l&#39;annulation d&#39;une impression active/en pause sur une imprimante prête, via le bouton HA existant, avec confirmation et nouvelle vérification de l&#39;état. Changer de profil n&#39;envoie aucune commande. Pas de consommation de filament ni de statistiques globales.</p><p>Affichage, caméra, graphiques et modification des profils vérifiés avec des entités réelles sous HA 2026.11.3, paramètres conservés. Également 16 tests automatisés et essais navigateur à 390, 800 et 1500 pixels sans débordement ni appel de service involontaire. Aucune impression réelle en cours n&#39;a été annulée pendant les essais.</p><h2 id="telechargements" tabindex="-1">Téléchargements <a class="header-anchor" href="#telechargements" aria-label="Permalink to &quot;Téléchargements&quot;">​</a></h2><ul><li><a href="https://github.com/rockbaer2007/3d-printer-card" target="_blank" rel="noreferrer">GitHub et guide complet</a></li><li><a href="https://github.com/rockbaer2007/3d-printer-card/releases/tag/v0.1.6" target="_blank" rel="noreferrer">Release 0.1.6 avec ZIP et JavaScript</a></li><li><a href="https://github.com/rockbaer2007/3d-printer-card/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">Historique des modifications</a></li></ul><p>Licence MIT. Projet frontend indépendant de l&#39;intégration Moonraker.</p>',16)])])}const h=r(n,[["render",s]]);export{m as __pageData,h as default};
